// tools/pokemonarena_w1_save.mjs -- TEST-ONLY: builds the SoulGold save file the W1 device journeys import.
//
// It starts from the REAL save the game itself wrote (tools/pokemonarena_savegen.mjs caches it as <tmp>/pokemonarena-sv1/real_v1.sav; it is
// regenerated by playing the new-game intro in the site's mGBA core when absent) and writes chosen Pokemon into its party and its first PC box
// with the savegen ENCODER (the same one the importer's own test uses), then recomputes the checksums. NOTHING ROM-DERIVED is written into the repo;
// the file lives in the OS temp dir.
//
//   import { makeArenaSave } from './pokemonarena_w1_save.mjs';
//   const { file, bytes, party, boxed } = await makeArenaSave({ rom, pack, outDir });
//
// The party is Sprigatito "Bob" (the game's own starter, kept as the real save has it), then PIKACHU Lv50 (Thunderbolt...), CHARIZARD Lv50,
// SNORLAX Lv50, each with four moves the rules accept; the first box holds GENGAR Lv50 (legal), EEVEE Lv30 (legal) and MAGIKARP Lv50 with
// Hyper Beam, a move it cannot learn (so it NEEDS FIXING). Used to prove the import screen's three statuses.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')), '..');
const G = await import(pathToFileURL(path.join(ROOT, 'tools/pokemonarena_savegen.mjs')).href);
const RU = await import(pathToFileURL(path.join(ROOT, 'pokemonarena/js/rules.js')).href);

const STATS6 = ['hp', 'atk', 'def', 'spe', 'spa', 'spd'];

export async function realSaveBytes(rom) {
  const file = path.join(G.SCRATCH, 'real_v1.sav');
  if (fs.existsSync(file)) return new Uint8Array(fs.readFileSync(file));
  const r = await G.generateRealSave({ rom, shotDir: path.join(G.SCRATCH, 'shots_real'), log: () => {} });
  fs.mkdirSync(G.SCRATCH, { recursive: true }); fs.writeFileSync(file, r.save);
  return new Uint8Array(r.save);
}

export async function makeArenaSave({ rom, pack, outDir = path.join(os.tmpdir(), 'pokemonarena-w1') } = {}) {
  const base = await realSaveBytes(rom);
  const layoutTable = G.readLayoutTable(Buffer.from(rom));
  const R0 = RU.resolveRuleset(RU.DEFAULT_RULESET_ID);
  const sup = RU.engineSupports(pack);
  const speciesId = (n) => pack.species.findIndex((s) => s && s.legal && s.name === n);
  const moveId = (n) => { const m = pack.moves.find((x) => x && x.name === n); return m ? m.id : 0; };
  let pidN = 0;
  function spec(name, level, nature, wanted, o = {}) {
    const id = speciesId(name), sp = pack.species[id];
    const pool = new Set(RU.legalMoves(pack, id, level, R0));
    const moves = [];
    for (const n of wanted) { const mid = moveId(n); if (mid && pool.has(mid) && sup.moves.has(mid) && !moves.includes(mid)) moves.push(mid); }
    for (const mid of pool) { if (moves.length >= 4) break; if (sup.moves.has(mid) && !moves.includes(mid)) moves.push(mid); }
    if (o.forceMoves) { moves.length = 0; moves.push(...o.forceMoves.map(moveId)); }
    const exp = pack.exp[sp.growthRate][level];
    const iv = {}, ev = {};
    for (const k of STATS6) { iv[k] = 31; ev[k] = o.ev && o.ev[k] ? o.ev[k] : 0; }
    const pid = (1000 + (++pidN)) * 25 + nature;               // personality % 25 = the nature; natureXor 0
    return { pid, tid: 31337, sid: 4242, nickname: o.nickname || '', otName: 'ASH', species: id, item: 0, ball: 4, exp, ppBonuses: 0, friendship: 70, moves, pp: moves.map(() => 20), iv, ev, hyper: {}, abilityNum: 0, shinyMod: 0, level, natureXor: 0, hp: 1, maxHp: 1, stats: { atk: 1, def: 1, spe: 1, spa: 1, spd: 1 } };
  }
  const specs = [
    spec('Pikachu', 50, 3, ['Thunderbolt', 'Quick Attack', 'Iron Tail', 'Thunder Wave'], { ev: { spe: 252, atk: 252 } }),
    spec('Charizard', 50, 10, ['Flamethrower', 'Dragon Claw', 'Earthquake', 'Air Slash'], { ev: { spa: 252, spe: 252 } }),
    spec('Snorlax', 50, 23, ['Body Slam', 'Earthquake', 'Rest', 'Crunch'], { ev: { hp: 252, def: 252 } }),
  ];
  const boxSpecs = [
    spec('Gengar', 50, 17, ['Shadow Ball', 'Thunderbolt', 'Hypnosis', 'Dream Eater']),
    spec('Eevee', 30, 0, ['Quick Attack', 'Bite', 'Tackle', 'Sand Attack']),
    spec('Magikarp', 50, 5, [], { forceMoves: ['Hyper Beam'], nickname: 'FISHY' }),
  ];
  // the real save's own party record (Bob) stays first, exactly as the game wrote it
  const { map } = G.slotMap(base, 1);
  const at = map.get(1) * 0x1000 + 0x238;
  const bob = base.slice(at, at + 96);
  let sav = G.withParty(base, layoutTable, 1, [bob, ...specs.map((s) => G.encodeMon(s, { party: true }))]);
  boxSpecs.forEach((s, i) => { sav = G.withBoxMon(sav, layoutTable, 1, 0, i, G.encodeMon(s, { party: false }).subarray(0, 76)); });
  fs.mkdirSync(outDir, { recursive: true });
  const file = path.join(outDir, 'arena-test.sav');
  fs.writeFileSync(file, sav);
  const brief = (s) => ({ species: s.species, name: pack.species[s.species].name, level: s.level, nature: s.pid % 25, moves: s.moves.slice() });
  return { file, bytes: sav, party: specs.map(brief), boxed: boxSpecs.map(brief) };
}
